			tabData.accept(CemmModBlocks.CUT_STRIPPED_DARK_OAK.get().asItem());
			tabData.accept(CemmModBlocks.CUT_BIRCH.get().asItem());
			tabData.accept(CemmModBlocks.CUT_STRIPPED_BIRCH.get().asItem());
